// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the deployer (this contract)
        address owner = address(this);

        // Call XBornID() - only owner can call
        c.XBornID();

        // In reference: balances[owner] = totalDistributed = 200000000e18
        // In bug: balances[owner] = totalSupply = 500000000e18
        // Check balanceOf(owner) to observe the difference
        uint256 balance = c.balanceOf(owner);

        // Reference holds: balance == 200000000e18
        // Bug breaks: balance == 500000000e18
        assertTrue(balance == 200000000e18, "balance should be totalDistributed");
    }
}

