    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Call XBornID() as owner to set owner's balance
        vm.prank(address(0x1)); // Use a non-owner address to avoid owner-only restriction
        // But XBornID() requires msg.sender == owner, so we need to call as owner
        // Owner is the deployer (address(this)), so we use address(this)
        // No prank needed
