// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up caller
        address alice = address(0xABCD);
        vm.deal(alice, 1 ether);

        // Call XBornID() as owner to initialize balances[owner]
        // (In the constructor, owner is msg.sender = address(this))
        // But the contract's XBornID() function requires msg.sender == owner
        // So we prank as address(this) which deployed the contract
        vm.prank(address(this));
        c.XBornID();

        // Now alice calls getTokens via receive to trigger distr
        vm.prank(alice);
        (bool ok, ) = address(c).call{value: 0.001 ether}("");
        require(ok, "receive failed");

        // In P totalDistributed increased by 1000e18, in M it did not change.
        // Now call burn on the owner (us) subtracting totalDistributed amount.
        // We need totalDistributed to be >0 for burn to subtract; in M it is still initial totalDistributed = 200000000e18.
        // But burn requires _value <= balances[msg.sender]; we have balances[owner]=totalDistributed.
        // To trigger a revert difference, we try to burn totalDistributed (which after P's distr is 200000000e18+1000e18 = 200001000e18).
        // But balances[owner]=200000000e18! So burn will revert in both because _value > balances[msg.sender].
        // Instead, we need to reduce totalDistributed such that a later subtraction underflows in M.
        // Actually, we can use a simpler approach: after distr, totalDistributed in P > totalDistributed in M.
        // The difference will affect totalRemaining = totalSupply - totalDistributed.
        // In getTokens, the calculation "if (value > totalRemaining) { value = totalRemaining; }" can behave differently.
        // But we need a hard divergence on a public getter.

        // Simpler: compare totalDistributed public variable after the calls.
        // In P: initial totalDistributed=200000000e18, after distr becomes 200001000e18.
        // In M: stays 200000000e18.
        // So assertEq(c.totalDistributed(), 200001000e18);
        // Passes on P, fails on M (M gives 200000000e18).
        assertEq(c.totalDistributed(), 200001000e18);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Pre-computed: after XBornID(), owner balance = totalDistributed = 200000000e18
        uint256 initialOwnerBalance = 200000000e18;
        uint256 transferAmount = 1e18;

        // Call XBornID() to initialize owner balance
        c.XBornID();

        // Verify owner balance before transfer
        assertEq(c.balanceOf(address(this)), initialOwnerBalance, "Owner balance should be initial after XBornID");

        // Perform a transfer from owner to another address (e.g., address(1))
        c.transfer(address(1), transferAmount);

        // After transfer, in the correct contract owner balance = initialOwnerBalance - transferAmount
        // In the buggy contract owner balance = initialOwnerBalance + transferAmount
        uint256 expectedCorrect = initialOwnerBalance - transferAmount;

        // Assert that the actual balance equals the expected correct value
        // This will pass on reference and fail on buggy because buggy gives wrong balance
        assertTrue(c.balanceOf(address(this)) == expectedCorrect, "Owner balance should decrease by transfer amount");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deployer is owner; call XBornID() to set balances[owner] = totalDistributed
        c.XBornID();

        // Now owner (address(this)) has 200000000e18 tokens; approve another address
        address alice = address(0x1234);

        // Owner approves alice to transfer 1 token
        c.approve(alice, 1000);

        // Get owner's balance before transferFrom
        uint256 balanceBefore = c.balanceOf(address(this));

        // Alice calls transferFrom from owner to alice, amount = 1000
        vm.prank(alice);
        c.transferFrom(address(this), alice, 1000);

        // Get owner's balance after transferFrom
        uint256 balanceAfter = c.balanceOf(address(this));

        // In reference, owner loses 1000: balanceAfter = balanceBefore - 1000
        // In mutant, owner gains 1000: balanceAfter = balanceBefore + 1000
        // Assert the reference behavior: balance decreases
        assertTrue(balanceAfter == balanceBefore - 1000);
    }
}

