        // Setup addresses
        address alice = address(0x1111);
        address bob = address(0x2222);

        // Alice approves bob for 5 tokens
        vm.prank(alice);
        c.approve(bob, 5);

        // Bob calls XBornID() (the contract's initialization function)
        vm.prank(bob);
        c.XBornID();

