// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1111);
    address bob = address(0x2222);

    function setUp() public { 
        c = new C(); 
    }

    function testRegression_property() public {
        // Setup: call XBornID() as owner to set initial balance
        vm.prank(address(this)); // msg.sender = this (owner)
        c.XBornID();

        // Alice gets tokens via getTokens()
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.getTokens{value: 0}();

        // Alice approves Bob to spend 100 tokens
        vm.prank(alice);
        c.approve(bob, 100);

        // Bob attempts to transferFrom alice to himself 10 tokens.
        // The correct contract reverts because the onlyPayloadSize modifier checks msg.data.length >= 32+4 = 36.
        // When Bob calls transferFrom(alice, bob, 10), msg.data length = 4 + 32*3 = 100, so it passes anyway.
        // To expose the difference, we need a call with msg.data length exactly at the boundary.
        // The buggy modifier allows msg.data.length >= 32, so any call with at least 32 bytes works.
        // The correct modifier requires at least 36 bytes. 
        // We can craft a call that has msg.data length = 32 (only 2 parameters) but is interpreted as transferFrom.
        // However, Solidity ABI requires 3 parameters for transferFrom (96 bytes data + 4 selector = 100 bytes).
        // The only way to hit the boundary is if the function selector is missing? No, the modifier checks msg.data.length >= size + 4 (where size is argument bytes). For transferFrom, size = 3*32 = 96, so it requires 100 bytes. Normal call has 100 bytes.
        // The buggy modifier requires msg.data.length >= 96. That's also satisfied by 100 bytes.
        // Both pass.
        // To differentiate, we must find a function where the argument size is small enough that removing 4 makes a difference.
        // For example, functions with size = 0 (no arguments) like balanceOf(address) has size = 32, correct requires 36, buggy requires 32.
        // So calling balanceOf with msg.data length = 32 (without selector offset) would revert in correct but pass in buggy.
        // But balanceOf is a view function, not state-changing. We need a state change.
        // The only function that can have size=0 modifier? onlyPayloadSize(0) would be weird. 
        // Actually, onlyPayloadSize is used for transfer (size=2*32=64) and transferFrom (size=3*32=96). For both, 4 bytes offset is minor.
        // But the modifier asserts on msg.data.length, which includes the function selector (4 bytes). For transfer, correct: >= 68, buggy: >=64. Both satisfied by normal call (68 bytes).
        // The only way they differ is if we call a function with a shorter ABI-encoded call, e.g., via low-level call.
        // Let's use vm.prank and raw call with insufficient data.
        // We'll call transfer(alice, 10) but with msg.data length = 67 bytes (64+3) which is <68 but >=64.
        // This will revert in correct (assert fails) but succeed in buggy (assert passes, then function executes).
        // But we need to observe the difference via public state.
        // After such a call, in the buggy version the transfer might succeed, changing balances. In the correct version it reverts.
        // Let's set up: alice has balance from XBornID()? Actually, after getTokens, alice gets some tokens.
        // But the XBornID() call gives totalDistributed to the owner, not to alice. We'll have owner send tokens to alice.

        // Reset: deploy fresh contract
        c = new C();
        vm.prank(address(this)); // owner
        c.XBornID(); // owner now has totalDistributed tokens

        // Owner transfers some to alice
        address owner = address(this);
        vm.prank(owner);
        c.transfer(alice, 1000);

        // Now alice has 1000 tokens. We'll call c.transfer(bob, 10) but with truncated msg.data.
        // We'll send a raw call to c with msg.data = abi.encodeWithSelector(bytes4(keccak256("transfer(address,uint256)")), bob, 10) <-- this is 68 bytes.
        // To get 67 bytes, we drop the last byte.
        bytes memory callData = abi.encodeWithSignature("transfer(address,uint256)", bob, 10);
        // callData length is 68. We'll create a shorter version (67 bytes) by removing the last byte.
        bytes memory shortData = new bytes(67);
        for (uint i = 0; i < 67; i++) {
            shortData[i] = callData[i];
        }

        // Alice makes this call
        vm.prank(alice);
        (bool success, ) = address(c).call(shortData);

        // In the correct version, the call reverts because assert(msg.data.length >= size + 4) fails (67 < 68).
        // In the buggy version, it passes (67 >= 64) and the transfer executes.
        // Now check Alice's balance. In correct, it remains 1000; in buggy, it becomes 990.
        uint256 aliceBalanceAfter = c.balanceOf(alice);

        // The correct reference has aliceBalanceAfter == 1000; the buggy has 990.
        assertTrue(aliceBalanceAfter == 1000, "Alice balance should be unchanged in correct version");
    }
}

