pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address spender = address(0x123);
        c.XBornID();

        // We want to test approve with msg.data.length exactly 36 (size 32 + 4 for selector).
        // The buggy version removes the +4 offset, so it would pass with 32 bytes of data.
        // To send exactly 32 bytes of data, we need to call a function that expects 28 bytes of data.
        // The only function that uses onlyPayloadSize(32) is approve, which requires 3 * 32 = 96 bytes normally.
        // But we can construct a raw call with abi.encodeWithSelector to send exactly 32 bytes.
        bytes memory callData = abi.encodeWithSelector(c.approve.selector, spender, 0);
        // This callData is 68 bytes (4+32+32). But we want exactly size = 32 => callData length 32 => 4 + 28 bytes.
        // We can truncate or use a different approach: call a function that has a modifier with size we can control.
        // Actually, the modifier onlyPayloadSize(size) checks msg.data.length >= size (correct) or >= size + 4 (bug).
        // The only function that uses onlyPayloadSize(size) in this contract is transfer (size=64) and transferFrom (size=96) and approve (doesn't have it).
        // Wait, approve does NOT use onlyPayloadSize. The only two functions with that modifier are transfer and transferFrom.
        // For transfer, size = 2 * 32 = 64. For transferFrom, size = 3 * 32 = 96.
        // So we need to trigger a transfer (or transferFrom) with msg.data.length = exactly 64 (correct reverts) or 68 (bug passes).
        // Actually the correct requires >= 68 (=64+4), bug requires >= 64. So call with 68 bytes passes both; call with 64 passes bug but reverts correct.
        // Therefore we can do: approve ourselves some tokens, then call transfer with artificially crafted msg.data of length 64.
        // The transfer function expects two uint256 parameters (to, amount) = 64 bytes of parameters + 4 selector = 68 total.
        // We can use vm.prank with a raw call that sends exactly 64 bytes of calldata.

        // First, give the caller some balance via distr (private but can be called via getTokens? Actually getTokens calls distr internally).
        // But getTokens requires distribution not finished, and value may be high. Let's directly call distr? No, it's private.
        // Simpler: just call XBornID which sets balances[owner] = totalDistributed.

        address caller = address(this);
        // After XBornID, balances[owner] = 200000000e18. So caller (owner) has balance.

        // Now craft a transfer call with msg.data.length = 64 (i.e., missing the 4 selector bytes for the offset).
        // We can use a low-level call where we manually pass the calldata.
        bytes memory shortCallData = abi.encodePacked(c.transfer.selector, uint256(uint160(address(0xbabe))), uint256(1));
        // shortCallData length = 4 + 32 + 32 = 68. We need exactly 64: remove 4 bytes from somewhere? Or we can use a different trick.
        // Actually we can call a function with onlyPayloadSize(32) but none exist except the modifier itself unused.
        // Let me re-check: onlyPayloadSize(2*32) on transfer, onlyPayloadSize(3*32) on transferFrom.
        // So the correct modifier requires >= 68 for transfer, >= 100 for transferFrom. Bug requires >= 64 for transfer, >= 96 for transferFrom.
        // So to get a difference, we need msg.data.length = 64..67 for transfer (correct reverts, bug passes) or 96..99 for transferFrom.
        // We can do: call transfer with exactly 64 bytes calldata. But how to generate exactly 64? 
        // Use a raw call: (bool ok, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.transfer.selector, address to, uint256 amount));
        // That gives 68 bytes. To get 64, we need to call a different function? Actually we can use assembly to truncate calldata.
        // Or we can use the fact that abi.encodePacked concatenates without padding, so we can produce a shorter calldata.
        // But the EVM expects properly encoded function arguments. This is messy.

        // Alternative: use the onlyPayloadSize(0) case? No, the modifier is only used with size = 64 or 96.
        // Let me use transferFrom: send calldata of length 96...99 by packing less bytes? Actually we can do: 
        // Craft calldata using abi.encodeWithSelector for transferFrom = 100 bytes. Then truncate to 96 bytes by reducing one argument? No.
        // It's simpler: we can use vm.etch or vm.assume? Not allowed.

        // Given complexity, I'll try a different approach: the bug is in the modifier onlyPayloadSize, which affects transfer and transferFrom.
        // To show divergence, we can simply call transfer with the exact msg.data length 68 and 64:
        // Both will fail (correct reverts at require, bug passes the modifier check but then likely fails at require _amount <= balances).
        // Actually the bug only changes the modifier check, not the require. So to see a difference in state, we need a call that:
        // - In correct version: modifier reverts (msg.data too short) -> state unchanged
        // - In buggy version: modifier passes, then require passes, then state changes.
        // So we need a valid transfer where the only obstacle is the modifier check, i.e., msg.data.length between 64 and 67 inclusive, and the balances/allowances are sufficient.

        // Let's craft a valid transfer call with 64 bytes of calldata. Since the correct expects >=68, it will revert at assert in modifier.
        // The buggy expects >=64, so it passes and executes the transfer.

        // To create a 64-byte calldata for transfer: the proper calldata is 4 bytes selector + 32 bytes to + 32 bytes amount = 68.
        // We can omit the last 4 bytes of the amount? That would be malformed. But the EVM will just read whatever is there.
        // Actually calldata is like an array: if the length is 64, then the last 4 bytes of the amount (which would be at bytes 60-63) are missing.
        // The EVM will read the 32 bytes of amount starting at offset 36, but only 28 bytes are present => it will pad with zeros at the end.
        // So the amount will be interpreted as a value with the last 4 bytes = 0, meaning a smaller number.
        // For simplicity, we can set the last 4 bytes of the amount to 0 in our call by using a value that has those bytes zero.
        // E.g., amount = 1 << 224 = 2^224, which has the last 28 bits zero? Actually 2^224 = 26959946667150639794667015087019630673637144422540572481103610249216, which in hex is 0x100000000000000000000000000000000000000000000000000000000, length 28 bytes, so the last 4 bytes of a 32-byte word would be 0x00000000.
        // That works. Let's do amount = 1 (which is 0x0...01, last 4 bytes are 0x00000001, not zero). Better use amount = 2^256 - 2^28 = ... Actually simpler: just use amount = 0 which is all zeros.
        // Transfer with amount 0: msg.data length 64 missing the last 4 bytes of the amount, but those missing bytes are zero anyway, so the amount is still 0.
        // So we can call transfer with to = some address and amount = 0, with calldata length = 64 (by removing the last 4 bytes of the amount which are 0).
        uint128 toLow = uint128(uint160(address(0xbabe)));
        uint128 amountLow = uint128(0);
        // Build calldata: selector (4) + to (32) + amount (32) = 68. Remove last 4 bytes of amount (which are the high bytes? No, amount is uint256, its last 4 bytes are the least significant bytes, which for 0 are 0x00000000). So we can just truncate the last 4 zero bytes.
        bytes memory calldata64 = abi.encodePacked(c.transfer.selector, toLow, amountLow);
        // Now calldata64 length = 4 + 16 + 16 = 36, not 64. We need 64.
        // Let's use proper padding: abi.encode(uint256(to), uint256(0)) gives 64 bytes. Add 4 selector => 68.
        // To get 64, we need to drop the last 4 bytes of the selector? No, selector must be first 4 bytes.
        // We can use assembly to create exactly 64 bytes:
        bytes memory data68 = abi.encodeWithSelector(c.transfer.selector, address(0xbabe), uint256(0));
        bytes memory data64;
        assembly {
            data64 := mload(0x40)
            mstore(data64, 64) // length = 64
            // copy first 64 bytes of data68 into data64
            let src := add(data68, 32)
            let dst := add(data64, 32)
            for { let i := 0 } lt(i, 64) { i := add(i, 32) } {
                mstore(dst, mload(src))
                src := add(src, 32)
                dst := add(dst, 32)
            }
            mstore(0x40, add(dst, 32))
